GA.i18n = {
  lang: null,
  init() { const s = localStorage.getItem("ga_lang"); this.lang = GA.config.languages.includes(s) ? s : GA.config.defaultLanguage; document.documentElement.lang = this.lang === "zh" ? "zh-CN" : this.lang; },
  set(l) { this.lang = l; localStorage.setItem("ga_lang", l); document.documentElement.lang = l === "zh" ? "zh-CN" : l; },
  t(path, vars) {
    const get = (d) => path.split(".").reduce((o, k) => (o == null ? o : o[k]), d);
    let v = get(GA.dict[this.lang]); if (v == null) v = get(GA.dict.it); if (v == null) v = path;
    if (vars && typeof v === "string") v = v.replace(/\{(\w+)\}/g, (_, k) => (k in vars ? vars[k] : ""));
    return v;
  },
  locale() { return { it: "it-IT", en: "en-GB", zh: "zh-CN" }[this.lang]; },
};
GA.t = (p, v) => GA.i18n.t(p, v);

